#include <iostream>
#include <string>

using namespace std;

bool canMakeABC(const string& s) {
    // Check if the current arrangement is already 'abc'
    if (s == "abc") return true;

    // Try swapping each pair of adjacent characters
    for (int i = 0; i < 2; ++i) {
        char temp = s[i];
        s[i] = s[i + 1];
        s[i + 1] = temp;

        // If the result is 'abc', return true
        if (s == "abc") return true;

        // Restore the original order before trying another swap
        temp = s[i];
        s[i] = s[i + 1];
        s[i + 1] = temp;
    }

    // No valid swap found
    return false;
}

