```javascript
function findObjectByName(obj, targetName) {
    const stack = [{ obj, path: [] }];

    while (stack.length > 0) {
        const { obj, path } = stack.pop();

        if (typeof obj === 'object' && obj !== null) {
            for (let key in obj) {
                if (obj.hasOwnProperty(key)) {
                    const newPath = [...path, key];
                    if (key === targetName) {
                        return { found: true, value: obj, path: newPath };
                    }
                    stack.push({ obj: obj[key], path: newPath });
                }
            }
        }
    }

    return { found: false, value: null, path: [] };
}

// Example usage:
const data = {
    a: {
        b: {
            c: {
                d: "target"
            },
            e: "notTarget"
        },
        f: "anotherNotTarget"
    }
};

const result = findObjectByName(data, 'd');
console.log(result); // { found: true, value: { d: "target" }, path: ["a", "b", "c"] }
```

This function uses a stack to simulate the traversal of the object graph iteratively. It keeps track of the current object and the path taken to get there. When it finds the object with the specified name, it returns both the object and the path. If the object is not found, it returns `false`.

