import numpy as np

class Model:
    def __init__(self):
        self.weights = None

    def update(self, context, action, reward):
        raise NotImplementedError("Subclasses must implement this method")

    def predict(self, context):
        raise NotImplementedError("Subclasses must implement this method")

class LinearModel(Model):
    def __init__(self, feature_dim):
        super().__init__()
        self.feature_dim = feature_dim
        self.weights = np.zeros(feature_dim)

    def update(self, context, action, reward):
        # Update weights using gradient descent or another method
        pass

    def predict(self, context):
        return np.dot(context, self.weights)

class RandomModel(Model):
    def __init__(self):
        super().__init__()

    def update(self, context, action, reward):
        # No updates needed for random model
        pass

    def predict(self, context):
        return np.random.rand()

class EpsilonGreedyBandit:
    def __init__(self, num_arms, epsilon=0.1):
        self.num_arms = num_arms
        self.epsilon = epsilon
        self.models = [LinearModel(5), LinearModel(5), RandomModel()]
        self.best_model_idx = 0

    def select_action(self, context):
        if np.random.rand() < self.epsilon:
            return np.random.choice(self.num_arms)
        else:
            predictions = [model.predict(context) for model in self.models]
            best_prediction = max(predictions)
            best_model_idx = predictions.index(best_prediction)
            return best_model_idx

    def update(self, context, action, reward):
        selected_model = self.models[action]
        selected_model.update(context, action, reward)

        # Optionally, re-evaluate the best model after each update
        new_predictions = [model.predict(context) for model in self.models]
        new_best_prediction = max(new_predictions)
        new_best_model_idx = new_predictions.index(new_best_prediction)
        if new_best_prediction > self.models[self.best_model_idx].predict(context):
            self.best_model_idx = new_best_model_idx

# Example usage
if __name__ == "__main__":
    bandit = EpsilonGreedyBandit(num_arms=3, epsilon=0.1)
    contexts = [np.random.rand(5) for _ in range(100)]
    rewards = [np.random.rand() for _ in range(100)]

    for t in range(len(contexts)):
        action = bandit.select_action(contexts[t])
        reward = rewards[t]
        bandit.update(contexts[t], action, reward)
```

### Explanation:
1. **Model Class**: A base class that defines the interface for all models.
2. **LinearModel Class**: Implements a linear model with weight updates and prediction methods.
3. **RandomModel Class**: A simple model that always returns a random value.
4. **EpsilonGreedyBandit Class**: Manages the selection of actions and updating of models. It uses an epsilon-greedy strategy to balance exploration and exploitation.
5. **Example Usage**: Demonstrates how to use the `EpsilonGreedyBandit` class with some simulated data.

