```systemverilog
class MyClass;
    rand bit [31:0] prev_output;
    rand bit [31:0] current_output;

    constraint c_transitions {
        // Calculate the number of transitions between prev_output and current_output
        int transition_count = $countones(current_output ^ prev_output);

        // Ensure the number of transitions is exactly 5
        transition_count == 5;
    }
endclass

module test;
