  Gl.attach_shader program (Gl.create_shader Gl.VertexShader) vertex_shader;
  Gl.attach_shader program (Gl.create_shader Gl.FragmentShader) fragment_shader;
  Gl.attach_shader program (Gl.create_shader Gl.ComputeShader) compute_shader;
  Gl.link_program program;
  program
in

let buffer = Gl.create_buffer () in
Gl.bind_buffer Gl.ArrayBuffer buffer;
