    #pragma HLS INTERFACE m_axi port=weights_hidden bundle=gmem1
    #pragma HLS INTERFACE m_axi port=biases_hidden bundle=gmem2
    #pragma HLS INTERFACE m_axi port=weights_output bundle=gmem3
    #pragma HLS INTERFACE m_axi port=biases_output bundle=gmem4
    #pragma HLS INTERFACE m_axi port=output_probabilities bundle=gmem5
    #pragma HLS INTERFACE s_axilite port=input_image bundle=control
    #pragma HLS INTERFACE s_axilite port=weights_hidden bundle=control
    #pragma HLS INTERFACE s_axilite port=biases_hidden bundle=control
    #pragma HLS INTERFACE s_axilite port=weights_output bundle=control
    #pragma HLS INTERFACE s_axilite port=biases_output bundle=control
    #pragma HLS INTERFACE s_axilite port=output_probabilities bundle=control
    #pragma HLS INTERFACE s_axilite port=return bundle=control

