class Action:
    def __init__(self, action_type, **kwargs):
        self.action_type = action_type
        self.kwargs = kwargs

    def execute(self, actor, target=None):
        if self.action_type == "deal_damage":
            return self._deal_damage(actor, target)
        elif self.action_type == "heal_actor":
            return self._heal_actor(actor)
