    def _deal_damage(self, actor, target):
        amount = self.kwargs.get("amount", actor.damage)
        target.hp -= amount
        print(f"{actor.name} deals {amount} damage to {target.name}.")
        return {"message": f"{actor.name} deals {amount} damage to {target.name}."}

    def _heal_actor(self, actor):
        amount = self.kwargs.get("amount", 10)
        actor.hp += amount
        print(f"{actor.name} heals itself for {amount} HP.")
        return {"message": f"{actor.name} heals itself for {amount} HP."}

    def _heal_target(self, target):
        amount = self.kwargs.get("amount", 10)
        target.hp += amount
        print(f"{target.name} is healed for {amount} HP.")
        return {"message": f"{target.name} is healed for {amount} HP."}

    def _deal_damage_based_on_health(self, actor, target):
        factor = self.kwargs.get("factor", 0.1)
        amount = int(target.hp * factor)
        target.hp -= amount
        print(f"{actor.name} deals {amount} damage to {target.name} based on its health.")
        return {"message": f"{actor.name} deals {amount} damage to {target.name} based on its health."}

    def _life_leech(self, actor, target):
        factor = self.kwargs.get("factor", 0.5)
        amount = int(target.hp * factor)
        target.hp -= amount
        actor.hp += amount
        print(f"{actor.name} deals {amount} damage to {target.name} and heals itself for {amount} HP.")
