```matlab
%% Water Wave Simulation: Fan-Generated Waves

% Parameters
L = 0.42; % Length of the tank (m)
W = 0.36; % Width of the tank (m)
U = 2.5;  % Wind speed (m/s)
g = 9.81; % Acceleration due to gravity (m/s^2)
h = 0.05; % Depth of the water (m)

% Grid setup
nx = 100; % Number of grid points in x-direction
ny = 100; % Number of grid points in y-direction
dx = L / (nx - 1); % Grid spacing in x-direction
dy = W / (ny - 1); % Grid spacing in y-direction

x = linspace(0, L, nx);
y = linspace(0, W, ny);
[X, Y] = meshgrid(x, y);

% Time parameters
dt = 0.01; % Time step (s)
T = 10;    % Total simulation time (s)
nt = T / dt; % Number of time steps

% Initialize variables
eta = zeros(nx, ny); % Surface elevation
u = zeros(nx, ny);   % Horizontal velocity
v = zeros(nx, ny);   % Vertical velocity

% Initial conditions
eta(:, :) = 0;
u(:, :) = 0;
v(:, :) = 0;

% Boundary conditions
bc = 'periodic'; % Periodic boundary conditions

% Simulation loop
for t = 1:nt
    % Update surface elevation using the shallow water equation
    eta_new = eta + dt * (u .* diff(u, 1, 2) ./ dx + v .* diff(v, 1, 1) ./ dy) ...
        + dt * g * (diff(eta, 1, 2) ./ dx + diff(eta, 1, 1) ./ dy);

    % Apply boundary conditions
    if strcmp(bc, 'periodic')
        eta_new(1, :) = eta_new(end, :);
        eta_new(end, :) = eta_new(1, :);
        eta_new(:, 1) = eta_new(:, end);
        eta_new(:, end) = eta_new(:, 1);
    end

    % Update velocities
    u = u + dt * (-diff(eta, 1, 2) ./ dx - diff(eta, 1, 1) ./ dy);
    v = v + dt * (-diff(eta, 1, 2) ./ dy - diff(eta, 1, 1) ./ dx);

    % Apply boundary conditions for velocities
    if strcmp(bc, 'periodic')
        u(1, :) = u(end, :);
        u(end, :) = u(1, :);
        u(:, 1) = u(:, end);
        u(:, end) = u(:, 1);

        v(1, :) = v(end, :);
        v(end, :) = v(1, :);
        v(:, 1) = v(:, end);
        v(:, end) = v(:, 1);
    end

    % Store the new surface elevation
    eta = eta_new;

    % Plot the surface elevation every 100 time steps
    if mod(t, 100) == 0
        figure;
        surf(X, Y, eta);
        title(['Surface Elevation at t = ', num2str(t*dt), ' s']);
        xlabel('X (m)');
        ylabel('Y (m)');
        zlabel('Elevation (m)');
        colorbar;
        drawnow;
    end
end

% Final plot
figure;
surf(X, Y, eta);
title('Final Surface Elevation');
xlabel('X (m)');
ylabel('Y (m)');
zlabel('Elevation (m)');
colorbar;
