Sure, I can help you with that! Here's a simple implementation of the Connect-4 game in Python:

```python
import numpy as np

# Define the size of the board
ROWS = 6
COLS = 7

# Initialize the board
board = np.zeros((ROWS, COLS))

def print_board(board):
    # Print the current state of the board
    for row in range(ROWS):
        print("|", end="")
        for col in range(COLS):
            if board[row][col] == 0:
                print("   |", end="")
            elif board[row][col] == 1:
                print(" X |", end="")
            else:
                print(" O |", end="")
        print()
    print("-" * (COLS * 4 + 1))
    for i in range(COLS):
        print(f" {i+1} ", end="")
    print()

def is_valid_location(board, col):
    # Check if the top row of the selected column is empty
    return board[0][col] == 0

def get_next_open_row(board, col):
    # Find the next available row in the selected column
    for r in range(ROWS - 1, -1, -1):
        if board[r][col] == 0:
            return r

def drop_piece(board, row, col, piece):
    # Place the player's piece on the board
    board[row][col] = piece

def winning_move(board, piece):
    # Check horizontal locations for win
    for c in range(COLS - 3):
        for r in range(ROWS):
            if all(board[r][c+i] == piece for i in range(4)):
                return True

    # Check vertical locations for win
    for c in range(COLS):
        for r in range(ROWS - 3):
            if all(board[r+i][c] == piece for i in range(4)):
                return True

    # Check positively sloped diagonals
    for c in range(COLS - 3):
        for r in range(ROWS - 3):
            if all(board[r+i][c+i] == piece for i in range(4)):
                return True

    # Check negatively sloped diagonals
    for c in range(COLS - 3):
        for r in range(3, ROWS):
            if all(board[r-i][c+i] == piece for i in range(4)):
                return True

    return False

def main():
    turn = 0
    game_over = False

    while not game_over:
        print_board(board)

        if turn % 2 == 0:
            col = int(input("Player 1 make your selection (1-7): ")) - 1
            piece = 1
        else:
            col = int(input("Player 2 make your selection (1-7): ")) - 1
            piece = 2

        if is_valid_location(board, col):
            row = get_next_open_row(board, col)
            drop_piece(board, row, col, piece)

            if winning_move(board, piece):
                print_board(board)
                print(f"Player {piece} wins!")
                game_over = True

        turn += 1

if __name__ == "__main__":
    main()
```

This code defines a basic Connect-4 game where two players take turns dropping their pieces into columns until one of them gets four in a row horizontally, vertically, or diagonally. The `print_board` function displays the current state of the board, and the other functions handle the logic for placing pieces and checking for a winner.

To run this script, make sure you have Python installed along with the NumPy library (`pip install numpy`). Then save the code to a file named `connect4.py` and execute it using the command `python connect4.py`. Enjoy playing Connect-4!

