use std::fs::File;
use std::io::{self, BufRead};
use std::process::Command;

fn main() -> io::Result<()> {
    let file = File::open("urls.txt")?;
    let reader = io::BufReader::new(file);

    for line in reader.lines() {
        let url = line?;

        if is_youtube_url(&url) {
            download_youtube_video(&url);
        }
    }

    Ok(())
}

fn is_youtube_url(url: &str) -> bool {
    url.starts_with("https://www.youtube.com/watch?v=")
        || url.starts_with("https://youtu.be/")
}

fn download_youtube_video(url: &str) {
    let output = Command::new("yt-dlp")
        .arg(url)
        .output()
        .expect("Failed to execute command");

    if !output.status.success() {
        eprintln!("Error downloading video: {}", String::from_utf8_lossy(&output.stderr));
    } else {
        println!("Video downloaded successfully!");
    }
}
```

