    </Grid>
</Window>

<!-- Custom control for drawing the Sierpinski Triangle -->
<UserControl x:Class="SierpinskiTriangle.SierpinskiTriangleControl"
             xmlns="http://schemas.microsoft.com/winfx/2006/xaml/presentation"
             xmlns:x="http://schemas.microsoft.com/winfx/2006/xaml"
             xmlns:mc="http://schemas.openxmlformats.org/markup-compatibility/2006" 
             xmlns:d="http://schemas.microsoft.com/expression/blend/2008" 
             mc:Ignorable="d" 
             d:DesignHeight="300" d:DesignWidth="400">
    <Canvas>
        <local:SierpinskiTriangle x:Name="triangle" Canvas.Left="100" Canvas.Top="10" />
    </Canvas>
</UserControl>

<!-- Code-behind for the custom control -->
using System.Windows;
using System.Windows.Controls;

namespace SierpinskiTriangle
{
    public partial class SierpinskiTriangle : UserControl
    {
        public SierpinskiTriangle()
        {
            InitializeComponent();
            DrawSierpinskiTriangle(100, 10, 200);
        }

        private void DrawSierpinskiTriangle(double x, double y, double size)
        {
            if (size > 10) // Base case: stop when the size is too small
            {
                var points = new PointCollection
                {
                    new Point(x, y),
                    new Point(x + size / 2, y - size * Math.Sqrt(3) / 2),
                    new Point(x + size, y)
                };

                var polygon = new Polygon { Points = points, Fill = Brushes.LightBlue, Stroke = Brushes.Black, StrokeThickness = 1 };
                this.Children.Add(polygon);

                // Recursively draw three smaller triangles
                DrawSierpinskiTriangle(x, y, size / 2);
                DrawSierpinskiTriangle(x + size / 2, y - size * Math.Sqrt(3) / 4, size / 2);
                DrawSierpinskiTriangle(x + size / 4, y + size * Math.Sqrt(3) / 4, size / 2);
            }
        }
    }
}
```

### Explanation:
1. **MainWindow.xaml**: This is the main window where we define the initial large triangle and include our custom `SierpinskiTriangleControl`.
2. **SierpinskiTriangleControl.xaml**: A user control that contains the logic for drawing the Sierpinski Triangle.
3. **SierpinskiTriangle.xaml.cs**: The code-behind file for the custom control, which includes the recursive method `DrawSierpinskiTriangle` to draw the fractal.

